	@Test
	@Timeout(120)
	void otherConnectionsWaitUntilTheImportIsComplete() throws Exception {
		LmdbStore sail = new LmdbStore(directory, config());
		sail.init();
		try {
			LmdbSailStore backing = sail.getBackingStore();
			LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection();
			try {
				writer.begin(IsolationLevels.NONE);
				addSubjects(writer, 0, 1_000);
				assertThat(backing.isInitialRunImportActive()).isTrue();

				CompletableFuture<Long> read = CompletableFuture.supplyAsync(() -> {
					// While any NONE transaction is open, LmdbStore serves reads from inside a NONE transaction only.
					try (LmdbStoreConnection reader = (LmdbStoreConnection) sail.getConnection()) {
						reader.begin(IsolationLevels.NONE);
						long size = reader.size();
						reader.commit();
						return size;
					}
				}, executor);
				CompletableFuture<Void> write = CompletableFuture.runAsync(() -> {
					try (LmdbStoreConnection other = (LmdbStoreConnection) sail.getConnection()) {
						other.begin(IsolationLevels.NONE);
						other.addStatement(subject(5_000), SHARED, SHARED);
						other.commit();
					}
				}, executor);
				Thread.sleep(500);
				assertThat(read).as("a reader waits for the store-wide import lock").isNotDone();
				assertThat(write).as("a writer waits for the store-wide import lock").isNotDone();

				addSubjects(writer, 1_000, 2_000);
				writer.commit();
				assertThat(read.get(30, TimeUnit.SECONDS)).as("the reader sees the whole import").isEqualTo(4_000L);
				write.get(30, TimeUnit.SECONDS);
			} finally {
				writer.close();
			}
			try (LmdbStoreConnection reader = (LmdbStoreConnection) sail.getConnection()) {
				assertThat(reader.size()).isEqualTo(4_001);
			}
		} finally {
			sail.shutDown();
		}
	}

